form.script:
var filterStr="&interfaceType=1";
function goFilter(buttonSearch)
{
getData($('#txtInterface')[0].value);
showPageContent();
}
function filterShowPorts()
{
filterStr = "&interfaceType=1";
getData();
showPageContent();
StylingInit();
}
function filterShowLAGS()
{
filterStr = "&interfaceType=2";
getData();
showPageContent();
StylingInit();
}
function filterShowALL()
{
filterStr = "";
getData();
showPageContent();
StylingInit();
}
function getData()
{
tmpl.wcd('wcd?{Standard802_3List' + filterStr + '}');
}
function drawSerch(element,index)
{
var htmlStr = ''+
'
