}
function showPageStaticContent()
{
drawTableIfFilter("dot1xAuthStatsTable",null,null,null,null,null,"interfaceFilter");
drawTableIfFilter("dot1xAuthStatsTable",null,null,null,null,null,"interfaceFilterFooter");
addButton("Cancel","",true);
addButton("Apply","",true);
bindButtonsToPanel();
disableControls(['Cancel','Apply'],true);
}
function showPageContent()
{
tmpl.bind($('#tmpl_PortsTableBody'), '#tblPorts_Body')
fillStandard802_3List();
SetSpan();
Validation.deregisterAll();
Validation.register($("#txtDescription")[0], "UnicodeString", false, [0,64]);
Validation.addPageHandler(checkValid);
}
function fillStandard802_3List()
{
var spanID, str;
$.each(tmpl.get.Standard802_3List,function(key, field)
{
str ="";
spanID = "span_adminMode_" + (key) + "_tblPORT";
if (field.adminState == "1")
str = "Enable";
else
str = "Disable";
setControlDataJQ(spanID,str);
str="";
spanID = "span_speedAdmin_" + (key) + "_tblPORT";
if(field.autoNegotiationAdminEnabled == "1")
str = "Auto";
else
str = (field.speedAdmin>0)? field.speedAdmin + "M" : "Auto";
if (str!= "Auto")
{
var contStr= field.duplexAdminMode
contStr = (contStr=="3") ? " Full" : " Half";
str =str + contStr + " Duplex"
}
$('#'+ spanID).text(str);
str = "";
spanID = "span_PhysicalStatus_" + (key) + "_tblPORT";
if(field.linkState == 1 && field.interfaceType != "2")
str = setPhysicalStatus(key,field.speedOper ,field.duplexOperMode);
$('#'+ spanID).text(str);
str ="";
spanID = "span_linkState_" + (key) + "_tblPORT";
str = (field.linkState > 1) ? "Link Down" : "Link Up" ;
$('#'+ spanID).text(str);
str ="";
spanID = "span_portType_" + (key) + "_tblPORT";
if(field.LAGID > 0)
str = "Port Channel";
else
{
str = portExistsInString(field.interfaceName, str)
}
$('#'+ spanID).text(str);
});
}
function setPhysicalStatus(index,speedVal, duplexVal)
{
var str, spanID;
str="";
spanID = "span_PhysicalStatus_" + (index) + "_tblPORT";
var duplexOperMode="";
switch(duplexVal)
{
case "1":
duplexOperMode = "Half";
break;
case "2":
duplexOperMode = "Full";
break;
case "3":
duplexOperMode = "Hybrid";
break;
case "4":
duplexOperMode = "Unknown";
break;
}
str = ((speedVal>0) ? speedVal : speedVal) + " Mbps " + duplexOperMode;
return str;
}
function portExistsInString(port, str)
{
$.each(tmpl.get.Standard802_3List,function(key, field)
{
if(field.srcInterfaceName == port)
str = "Mirrored";
else if(field.destInterfaceName == port)
str = "Probe";
});
return str;
}
function setSpeed()
{
$.each(tmpl.get.Standard802_3List,function(key, field)
{
if(field.autoNegotiationAdminEnabled == 1)
str = "Auto";
else
str = "M";
});
return str;
}
function checkValid()
{
return true;
}
function SetButtons()
{
AlterTableButtons(selectedCheckBoxCounter["dot1xAuthStatsTable"], null , "Apply" ,"Cancel", null);;
}
function SetSpan()
{
var count=0;
var index;
$.each(tmpl.get.Standard802_3List,function(key, field)
{
if($("#tblList_cb" + (key))[0].checked==true)
{
count++;
index = key;
}
});
if(count == 1)
{
setInnerText(document.getElementById("tdPort"),getInnerText(document.getElementById("td_port_" + (index) + "_tblPORT")));
setInnerText(document.getElementById("txtDescription"),getInnerText(document.getElementById("span_Description_" + (index) + "_tblPORT")));
$("#txtDescription")[0].disabled = false;
$("#txtDescription")[0].style.backgroundColor = "";
setInnerText(document.getElementById("tdPortType"),getInnerText(document.getElementById("span_portType_" + (index) + "_tblPORT")));
if(tmpl.get.Standard802_3List[index].autoNegotiationAdminEnabled == "1")
$("#slctPortSpeed")[0].value = "0";
else
{
var speedAdmin= tmpl.get.Standard802_3List[index].speedAdmin
var duplexAdminMode= tmpl.get.Standard802_3List[index].duplexAdminMode
duplexAdminMode = (duplexAdminMode=="3") ? "F" : "H";
var str = speedAdmin+duplexAdminMode
$("#slctPortSpeed")[0].value = str
}
setInnerText(document.getElementById("tdPhysicalStatus"),setPhysicalStatus(index,tmpl.get.Standard802_3List[index].speedOper,tmpl.get.Standard802_3List[index].duplexOperMode));
setInnerText(document.getElementById("tdLinkStatus"),getInnerText(document.getElementById("span_linkState_" + (index) + "_tblPORT")));
setInnerText(document.getElementById("tdMACAddress"),getInnerText(document.getElementById("span_MACAddress_" + (index) + "_tblPORT")));
setInnerText(document.getElementById("tdifIndex"),getInnerText(document.getElementById("span_interfaceID_" + (index) + "_tblPORT")));
}
else
{
setInnerText(document.getElementById("tdPort"),"");
setInnerText(document.getElementById("txtDescription"),"");
$("#txtDescription")[0].disabled = false;
$("#txtDescription")[0].style.backgroundColor = "";
setInnerText(document.getElementById("tdPortType"),"");
$("#slctAdminMode")[0].selectedIndex = 0;
$("#slctPortSpeed")[0].selectedIndex = 0;
setInnerText(document.getElementById("tdPhysicalStatus"),"");
setInnerText(document.getElementById("tdLinkStatus"),"");
setInnerText(document.getElementById("tdMACAddress"),"");
setInnerText(document.getElementById("tdifIndex"),"");
}
}
function getApplyPostData(post)
{
if(!Validation.pass(true))
return post;
var isLAG = false;
$("#chkAll")[0].checked=false
var selectedIndexes = new Array();
$('[id^="tblList_cb"]:checked').each(function () {
selectedIndexes.push(parseInt(this.value,10)).toString();
});
post.Standard802_3List = { set: [] };
for (var i = 0 ; i < selectedIndexes.length ; i++)
{
var interfaceName = getControlDataJQ("td_port_" + selectedIndexes[i] + "_tblPORT");
var interfaceType = tmpl.get.Standard802_3List[selectedIndexes[i]].interfaceType;
var interfaceID = getControlDataJQ("span_interfaceID_" + selectedIndexes[i] + "_tblPORT");
var interfaceDescription = getControlDataJQ("txtDescription");
var adminState = getControlDataJQ("slctAdminMode");
var speedAdmin = (getControlDataJQ("slctPortSpeed",false)>0) ? ""+ getControlDataJQ("slctPortSpeed",false) +"" : getControlDataJQ("slctPortSpeed",false);
var autoNegAdmin = (speedAdmin == "0") ? "1" : "2";
var duplexAdmin;
if(speedAdmin == "")
duplexAdmin = "";
else if(speedAdmin == "0")
duplexAdmin = "3";
else
{
var duplexCode = speedAdmin.charAt(speedAdmin.length - 1);
duplexAdmin = (duplexCode == "H") ? "2" : "3";
speedAdmin = parseInt(speedAdmin,10);
}
var LAGID = tmpl.get.Standard802_3List[selectedIndexes[i]].LAGID;
if(LAGID > 0 )
isLAG = true
post.Standard802_3List.set.push(
{
Entry:
{
interfaceName:interfaceName,
interfaceType:interfaceType,
interfaceID:interfaceID,
interfaceDescription:interfaceDescription,
adminState:(adminState != "") ? adminState : undefined,
autoNegotiationAdminEnabled:(speedAdmin != "") ? autoNegAdmin : undefined,
speedAdmin:(speedAdmin != "") ? speedAdmin.toString() : undefined,
duplexAdminMode:(duplexAdmin != "") ? duplexAdmin : undefined
}
});
}
if (isLAG == true)
alert("The configuration on port won’t take effect until the port is taken out of the LAG.");
disableControls(['Cancel','Apply'],true);
return post;
}
function updatePageMethod()
{
checkPortFromDevice();
}
function checkPortFromDevice()
{
if(top.deviceContextNum != null)
{
var chkBoxElm = document.getElementById("tblList_cb" + top.deviceContextNum);
chkBoxElm.checked = true;
chkBoxElm.onclick();
top.deviceContextNum = null;
}
}
